def caesar_decrypt(s, shift):
    out = []
    for ch in s:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base - shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def rot13(s):
    return caesar_decrypt(s, 13)

def atbash(s):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 'A' if ch.isupper() else 'a'
            idx = ord(ch) - ord(base)
            out.append(chr(ord(base) + (25 - idx)))
        else:
            out.append(ch)
    return ''.join(out)

def vigenere_decrypt(ct, key):
    out = []
    j = 0
    for ch in ct:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            k = ord(key[j % len(key)].lower()) - ord('a')
            out.append(chr((ord(ch) - base - k) % 26 + base))
            j += 1
        else:
            out.append(ch)
    return ''.join(out)

DICT = {"picnic","is","in","plaza","square","park","polybius","ptolemy"}

def score(text):
    tokens = [''.join(c for c in w if c.isalpha()).lower() for w in text.split()]
    return sum(1 for t in tokens if t in DICT)

